"""Present all rescues/harms and qualify observational findings."""
from pathlib import Path
import json
from collections import Counter
O=Path(__file__).resolve().parent;R=O.parents[1];read=lambda n:json.loads((O/n).read_text(encoding='utf-8-sig'))
rows=read('sample_contributions.json');old={r['sample_id']:r for r in json.loads((R/'analysis/error_evidence_linkage_20261025/all_training_linked.json').read_text(encoding='utf-8-sig'))};arms=['fusion_3Di4','fusion_masked4'];coverage=read('matching_coverage.json')
extra=[]
for arm in arms:
 rescued=[r for r in rows if r[arm]['role']=='corrected'];harmed=[r for r in rows if r[arm]['role']=='harmed']
 extra.append(dict(arm=arm,rescue_n=len(rescued),rescue_already_correct_in_historical_canonical=sum(old[r['sample_id']]['fusion_error']=='False' for r in rescued),rescue_also_historical_canonical_errors=sum(old[r['sample_id']]['fusion_error']=='True' for r in rescued),harm_also_historical_canonical_errors=sum(old[r['sample_id']]['fusion_error']=='True' for r in harmed),rescues_with_curated_family=sum(bool(r['curated_family']) for r in rescued),rescues_with_any_name_proxy=sum(bool(r['name_class']) for r in rescued),rescues_with_no_database_name=sum(not bool(r['name']) for r in rescued),rescues_with_cross_source_label_conflict=sum(r['cross_source_label_conflict'] for r in rescued)))
(O/'historical_model_overlap_and_annotation_coverage.json').write_text(json.dumps(extra,ensure_ascii=False,indent=2),encoding='utf-8')
lines=['# SaProt纠错/添错完整样本清单','','主比较为同规模4成员冻结表征基线，不是完整canonical GHXTox。标签不作修改；名称/家族/机制仅来自已有缓存。相近序列配对和全部概率见JSON。','']
for arm in arms:
 for role,title in [('corrected','纠正的错题'),('harmed','新增的错题')]:
  selected=[r for r in rows if r[arm]['role']==role];lines += [f'## {arm}：{title}（{len(selected)}条）','','|ID|标签|折|名称|基线概率→融合概率|两种子均复现该方向|历史完整GHXTox也错|','|---|---:|---:|---|---|---|---|']
  for r in selected:
   a=r[arm];stable=all(a['seed_roles'][str(seed)]==role for seed in [20261026,20261027]);name=r['name'].replace('|','/').replace('\n',' ') or '无缓存名称'
   lines.append(f"|{r['sample_id']}|{r['label']}|{r['fold']}|{name}|{r['baseline4_probability']:.4f}→{a['probability']:.4f}|{'是' if stable else '否'}|{'是' if old[r['sample_id']]['fusion_error']=='True' else '否'}|")
(O/'SAMPLE_LIST.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
lines=['# SaProt贡献：整类样本分析','','结论：固定融合的互补收益真实存在于本轮OOF；最稳定的群体现象是减少低Cys原负类的误报。没有证据表明它补上了溶血机制，或已学到二硫键拓扑。暂不把它作为所有样本的统一三维教师。','','## 口径与已有结果','','复用6387条、同一分组五折的已核验预测和缓存注释，不重训编码器/分类器，不重算整体MCC检验，不修改标签。不使用Test1/Test2。主比较为同为4成员的冻结ProtT5特征小分类头与SaProt固定融合；这不是完整canonical GHXTox的性能提升。另列历史完整模型错误重叠，防止混淆。','','|候选|纠错|添错|净少错|原负类净少错|原正类净少错|','|---|---:|---:|---:|---:|---:|','|保留近似3Di结构|101|63|38|34|4|','|遮住全部结构|96|62|34|22|12|','','结构版101条纠错占基线450条错题的22.4%，63条添错占5937条原正确样本的1.06%。正负类分开看，避免总体指标掩盖漏判风险。','','## 哪些规律比较稳定','','- 两融合共同纠正70条；结构版特有31条、掩码版特有26条。这些是现有预测的交集，不是可凭真实标签部署的选择器。','- 结构版五折净少错分别7、7、9、6、9；全掩码版8、4、0、11、11。群体互补跨折存在。','- 101条结构版纠错中48条在两个单种子配对中都仍是纠错；掩码版96条中45条。个体稳定性有限，不能把整份纠错名单都当成稳定机制样本。单种子比较是同种子基线与2头融合，主比较是4头与4头，口径不同。','','|结构版分层|纠错|添错|净少错|五折净变化|','|---|---:|---:|---:|---|','|原负类，Cys<4|47|15|32|6/12/9/4/1|','|原负类，Cys≥4|12|10|2|-1/4/-1/0/0|','|原正类，Cys<4|20|28|-8|2/-10/-1/-1/2|','|原正类，Cys≥4|22|10|12|0/1/2/3/6|','','低Cys原负类净减少32条误报，两单种子比较分别净减少42、41条，原群bootstrap95%区间折算约[16.2,48.0]条，是最清楚的互补方向。原正类总体仅净减少4条漏判，区间约[-14.0,23.2]，不能说毒性检出已稳定改善。分层区间为探索性、未做多重校正，不能独立升级为确认结论。','','纠错负类平均Cys1.63个，未纠错负类3.42个；纠错正类3.55个，未纠错正类1.05个。Cys数量及跨度的两类差异在5折和两个种子均同向，两融合都有。19项固定特征×2标签×2候选共76项探索比较进行了BH校正。较长正类也更易纠正。它们可能反映已存在的类别/家族差异，不能据此认定Cys本身造成毒性，或设计一个按Cys硬切换的模型。','','## 生物学候选因素的核查','','|候选因素|本轮观察|结论|','|---|---|---|','|二硫键/拓扑|Cys相关描述差异可重复；明确二硫键注释的正类24条，结构版纠1添4|Cys多不等于二硫键连接被识别，不能称拓扑机制已补强|','|膜作用/溶血线索|76条注释阳性中，结构版纠0添6；全掩码纠2添2|没有补上原先关心的膜作用盲区；原注释包含否定语义，非统一实验金标准|','|通道靶点线索|395条注释正类，结构版纠6添4；掩码版纠8添4|小幅互补，未显示结构版特异机制优势|','|化学修饰|明确修饰注释正类42条，结构版纠1添3；掩码版纠2添2|未显示修饰机制补强；注释缺失不当作未修饰|','|空间疏水接触/紧致度/电荷疏水分离|部分未经背景控制的描述差异可重复；扣除长度、Cys、净电荷、平均疏水性、pLDDT及基线概率后，12项比较BH均未通过|不足以支持新的空间机制模块；线性背景扣除也不是因果检验|','','空间背景扣除只拟合特征的Ridge回归，不训练毒性分类器；每个外折由其他折拟合，当前行不参与自身背景回归。事后跟进协议单独保留；最初说明误写BH6，实际2候选×2标签×3空间特征=12项，代码与结果按更完整的BH12执行，保留该修正记录。','','## 家族和相近序列控制','','严格同标签、同折、不同序列群、长度比≥0.7，优先明确家族，其次名称类别，再序列近似；全局相同率≥40%、配对覆盖两侧≥70%。未匹配样本保留，未放宽规则凑数量。序列候选搜索最多30个三肽相似候选，家族候选全查，因此覆盖率不是所有可能匹配的理论上限。','','|候选|纠错↔仍错对照|纠错↔始终正确对照|明确家族配对总数|','|---|---:|---:|---:|',f"|结构版|{coverage[arms[0]]['persistent_wrong']['n_pairs']}|{coverage[arms[0]]['persistent_correct']['n_pairs']}|2|",f"|掩码版|{coverage[arms[1]]['persistent_wrong']['n_pairs']}|{coverage[arms[1]]['persistent_correct']['n_pairs']}|0|",'', '结构版12对仍错对照中，负类仅4对，Cys差均值+0.25；正类8对，Cys差+0.375、长度差-0.25。整体Cys/长度差异在近背景小样本中明显减弱，不支持把总体相关当成家族内机制。结构版28对始终正确对照也没有统一的疏水接触或紧致度方向。明确家族仅2对，多数是序列或名称代理，不是实验条件一致对照。不同角色的对照独立分配，不能把全体配对当作互不相关的独立实验。','','## 贡献是否特别来自三维','','结构版与掩码版共同收益很大，且1295条完全没有保留3Di的样本也有收益。真正保留结构token的原正类1267条中，结构版比掩码版多纠正13条、同时多错23条，净多10条错误；原负类则净少10条。全部token被掩码的样本中两头输出仍可能不同，因为训练时其他样本不同，不能把这种输出差当作当前样本的三维证据。','','101条结构版纠错不全来自边界：其中仅23条原概率距离0.5不超过0.1，45条不超过0.2。故不能仅解释为把阈值边缘挪过线；但概率差仍不能证明机制，且成员替换、校准和表征差异共同影响它。','','## 历史完整GHXTox的重叠（只作定位）','','|候选|本轮纠错|历史完整模型也错|历史完整模型原本已对|','|---|---:|---:|---:|']
for r in extra:lines.append(f"|{r['arm']}|{r['rescue_n']}|{r['rescue_also_historical_canonical_errors']}|{r['rescue_already_correct_in_historical_canonical']}|")
lines += ['', '此交集不等于把SaProt加入完整GHXTox后的改进，也不据此重选历史阈值。跨源标签冲突的328条仅为疑点，结构版纠错仅4条，净少错3条；排除它们的其余原负类仍净少错31条，收益并非主要依赖这些争议标签。','','## 下一步具体任务','','先保留两个融合为候选，冻结蒸馏比较之前明确两类验收：总体MCC/AUPRC，以及低Cys正类、76条膜线索类的漏判变化。加入4基线教师自蒸馏控制，判断是否是SaProt特有互补；全掩码控制不能省。不得按当前真实标签设计路由、挑纠错样本单独自评或把全部教师输出当可靠答案。','','本轮不新增膜/修饰/拓扑网络。若研究目标仍是生物学机制创新，当前结果提供的是一个需要解释的选择性盲区：两融合对低Cys原正类净添错，而非已经发现的新机制。需要后续冻结的同背景检验支持，不能仅给相关特征换一个网络名称。','','## 交付与验证','','[完整纠错/添错名单](SAMPLE_LIST.md)、sample_contributions.json（全部6387条含序列、概率、种子、注释、来源）、matched_controls.json、feature_comparisons.json、adjusted_spatial_comparisons.json、subgroup_net_uncertainty.json以及verification.json均在本目录。所有输入文件哈希保持一致。整轮没有重训毒性模型、没有服务器费用。']
(O/'REPORT.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print(json.dumps(extra,ensure_ascii=False,indent=2))
